from pathlib import Path


def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f'{label}: expected source not found')
    return text.replace(old, new, 1)

# Shell: single global edit entry + focused card editor, while preserving AppConfig/local-first ownership.
p = Path('js/core/shell-ui.js')
text = p.read_text(encoding='utf-8')
text = replace_once(
    text,
    "let activeAction='home',menuGroup=null,visibilityObserver=null,headerPopover=null,themeTouched=false,nativeBackBound=false,browserBackBound=false,browserExitApproved=false;",
    "let activeAction='home',menuGroup=null,menuEditing=false,visibilityObserver=null,headerPopover=null,themeTouched=false,nativeBackBound=false,browserBackBound=false,browserExitApproved=false;",
    'shell menu state'
)
text = replace_once(
    text,
    "function closeMenu(){const layer=$('#kaMenuLayer');if(layer){layer.classList.remove('open');layer.hidden=true;layer.innerHTML=''}menuGroup=null;document.body.classList.remove('ka-layer-open')}",
    "function closeMenu(){const layer=$('#kaMenuLayer');if(layer){layer.classList.remove('open');layer.hidden=true;layer.innerHTML=''}menuGroup=null;menuEditing=false;document.body.classList.remove('ka-layer-open')}",
    'closeMenu editing reset'
)
start = text.find('function menuLayoutConfig(){')
end = text.find('function syncVisibilityClasses(){', start)
if start < 0 or end < 0:
    raise SystemExit('shell menu render block not found')
block = r'''function menuLayoutConfig(){const v=global.AppConfig?.get?.()?.menuLayout;return v&&typeof v==='object'?v:{groups:{}}}
function validMenuColor(v){v=String(v||'').trim();return /^#[0-9a-f]{6}$/i.test(v)?v:''}
function menuItemKey(g,item){return `${String(g?.key||'')}:${String(item?.[2]||'')}:${String(item?.[3]||'root')}:${String(item?.[0]||'')}`}
function legacyMenuItemKey(g,item){return `${String(g?.key||'')}:${String(item?.[2]||'')}:${String(item?.[3]||'root')}`}
function menuItemView(g,item,index,groupSettings){const items=groupSettings?.items||{},s=items[menuItemKey(g,item)]||items[legacyMenuItemKey(g,item)]||{},x=[...item],order=Number(s.order);x[0]=String(s.label||item?.[0]||'');x[1]=String(s.icon||item?.[1]||'');x.__menuColor=validMenuColor(s.color);x.__menuVisible=s.visible!==false;x.__menuOrder=Number.isFinite(order)?order:(index+1)*10;return x}
function menuGroupView(g,index){const s=menuLayoutConfig()?.groups?.[g.key]||{},order=Number(s.order),x={...g};x.label=String(s.label||g.label||'');x.icon=String(s.icon||g.icon||'');x.__menuColor=validMenuColor(s.color);x.__menuVisible=s.visible!==false;x.__menuOrder=Number.isFinite(order)?order:(index+1)*10;x.items=(g.items||[]).map((item,i)=>menuItemView(g,item,i,s)).filter(item=>item.__menuVisible).sort((a,b)=>a.__menuOrder-b.__menuOrder);x.subItems=(g.subItems||[]).map((item,i)=>menuItemView(g,item,(g.items||[]).length+i,s)).filter(item=>item.__menuVisible).sort((a,b)=>a.__menuOrder-b.__menuOrder);return x}
function visibleItems(g){return(g.items||[]).filter(itemAllowed).concat((g.subItems||[]).filter(itemAllowed))}
function visibleGroups(){return MENU_GROUPS.filter(g=>g.hidden!==true&&visibleItems(g).length)}
function customizedVisibleGroups(){return visibleGroups().map((g,index)=>menuGroupView(g,index)).filter(g=>g.__menuVisible!==false&&visibleItems(g).length).sort((a,b)=>a.__menuOrder-b.__menuOrder)}
function menuCount(g){return visibleItems(g).length}
function menuGroupAttrs(g){return g.__menuColor?` data-menu-custom-color="true" style="--ka-menu-custom:${g.__menuColor}"`:''}
function menuItemAttrs(item){return item.__menuColor?` data-menu-custom-color="true" style="--ka-menu-item-custom:${item.__menuColor}"`:''}
const MENU_CARD_DEFAULT_COLORS=Object.freeze({people:'#18a77f',exams:'#2f80ed',communication:'#ef5b50',programs:'#d7b226',calendar:'#2fa8c8',transport:'#7554d8',documents:'#ed922c',management:'#2d8a48',settings:'#64717f'});
const MENU_CARD_COLOR_PRESETS=Object.freeze(['#7554d8','#2f80ed','#18a77f','#d7b226','#ed922c','#ef5b50','#2fa8c8','#64717f']);
const MENU_CARD_ICON_PRESETS=Object.freeze(['👥','📝','📅','💬','📆','🚌','📁','🧑‍💼','⚙️','🗂️']);
function canEditMenu(){const u=user();return u.admin===true||global.PermissionService?.can?.('settings.app.edit','edit')===true}
function menuCardDefaultColor(key){return MENU_CARD_DEFAULT_COLORS[key]||'#17684f'}
function renderMenuGrid(){const layer=$('#kaMenuLayer');if(!layer)return;menuGroup=null;const cards=customizedVisibleGroups(),editable=canEditMenu();layer.innerHTML=`<div class="ka-menu-page"><div class="ka-menu-head"><h2>Menü</h2><div class="ka-menu-head__actions">${editable?`<button class="ka-menu-edit-toggle ${menuEditing?'is-active':''}" type="button" data-ka-menu-edit>${menuEditing?'✓ Bitti':'✎ Düzenle'}</button>`:''}<button class="ka-icon-button" type="button" data-ka-menu-close aria-label="Kapat">${SVG.close}</button></div></div><div class="ka-menu-grid ${menuEditing?'ka-menu-grid--editing':''}">${cards.map(g=>`<button class="ka-menu-card ka-menu-card--${g.tone}" type="button" data-ka-menu-group="${g.key}" aria-label="${esc(menuEditing?`${g.label} kartını düzenle`:g.label)}"${menuGroupAttrs(g)}>${menuEditing?'<span class="ka-menu-card__edit-indicator" aria-hidden="true">✎</span>':''}<span class="ka-menu-card__icon">${g.icon}</span><strong>${esc(g.label)}</strong><span class="ka-badge">${menuCount(g)}</span></button>`).join('')}</div></div>`;layer.querySelector('[data-ka-menu-close]')?.addEventListener('click',closeMenu);layer.querySelector('[data-ka-menu-edit]')?.addEventListener('click',()=>{menuEditing=!menuEditing;renderMenuGrid()});layer.querySelectorAll('[data-ka-menu-group]').forEach(b=>b.addEventListener('click',()=>menuEditing?renderMenuCardEditor(b.dataset.kaMenuGroup):renderMenuList(b.dataset.kaMenuGroup)))}
function listRow(item){return `<button type="button" class="ka-btn ka-btn--secondary" data-ka-shell-route="${item[2]}" data-ka-shell-page="${item[3]||''}" data-ka-shell-title="${esc(item[0])}"${menuItemAttrs(item)}><span class="ka-avatar">${item[1]}</span><span class="ka-grow"><strong>${esc(item[0])}</strong></span><span>${SVG.chevron}</span></button>`}
function renderMenuList(key){const layer=$('#kaMenuLayer'),g=customizedVisibleGroups().find(x=>x.key===key);if(!layer||!g)return;menuGroup=key;const main=(g.items||[]).filter(itemAllowed),sub=(g.subItems||[]).filter(itemAllowed);layer.innerHTML=`<div class="ka-menu-page"><div class="ka-menu-head"><button class="ka-icon-button" type="button" data-ka-menu-back aria-label="Geri">${SVG.back}</button><h2>${esc(g.label)}</h2><button class="ka-icon-button" type="button" data-ka-menu-close aria-label="Kapat">${SVG.close}</button></div><div class="ka-stack ka-page ka-menu-list">${main.map(listRow).join('')}${sub.length?`<h3>${esc(g.subLabel||'Diğer')}</h3>${sub.map(listRow).join('')}`:''}</div></div>`;layer.querySelector('[data-ka-menu-back]')?.addEventListener('click',()=>{menuEditing=false;renderMenuGrid()});layer.querySelector('[data-ka-menu-close]')?.addEventListener('click',closeMenu);bindMenuRoutes(layer)}
function menuEditorIcons(current){return [...new Set([current,...MENU_CARD_ICON_PRESETS].filter(Boolean))]}
function menuEditorColors(current){return [...new Set([current,...MENU_CARD_COLOR_PRESETS].filter(validMenuColor))]}
function renderMenuCardEditor(key){const layer=$('#kaMenuLayer'),g=customizedVisibleGroups().find(x=>x.key===key),base=MENU_GROUPS.find(x=>x.key===key);if(!layer||!g||!base||!canEditMenu())return;const color=g.__menuColor||menuCardDefaultColor(key),icons=menuEditorIcons(g.icon),colors=menuEditorColors(color);layer.innerHTML=`<div class="ka-menu-editor-screen"><section class="ka-menu-editor-sheet" role="dialog" aria-modal="true" aria-labelledby="kaMenuEditorTitle"><div class="ka-menu-editor-grip" aria-hidden="true"></div><header class="ka-menu-editor-head"><div><small>KART ÖZELLEŞTİRME</small><h2 id="kaMenuEditorTitle">Menü Kartını Düzenle</h2></div><button class="ka-icon-button" type="button" data-menu-editor-cancel aria-label="Kapat">${SVG.close}</button></header><div class="ka-menu-editor-body"><section class="ka-menu-editor-section"><span class="ka-menu-editor-label">ÖNİZLEME</span><article class="ka-menu-editor-preview" style="--ka-menu-editor-color:${color}"><span class="ka-menu-editor-preview__icon" data-menu-editor-preview-icon>${g.icon}</span><strong data-menu-editor-preview-label>${esc(g.label)}</strong><span class="ka-menu-editor-preview__badge">${menuCount(g)}</span></article></section><section class="ka-menu-editor-section"><label class="ka-menu-editor-label" for="kaMenuEditorLabel">MENÜ ADI</label><div class="ka-menu-editor-input-wrap"><input id="kaMenuEditorLabel" data-menu-editor-label-input maxlength="36" value="${esc(g.label)}"><small data-menu-editor-counter>${String(g.label||'').length}/36</small></div></section><section class="ka-menu-editor-section"><span class="ka-menu-editor-label">İKON</span><div class="ka-menu-editor-icon-grid">${icons.map(icon=>`<button type="button" class="ka-menu-editor-icon-option ${icon===g.icon?'is-selected':''}" data-menu-editor-icon="${esc(icon)}" aria-label="${esc(icon)} ikonunu seç">${icon}</button>`).join('')}</div><label class="ka-menu-editor-custom-icon"><span>Özel ikon / emoji</span><input data-menu-editor-icon-input maxlength="8" value="${esc(g.icon)}"></label></section><section class="ka-menu-editor-section"><span class="ka-menu-editor-label">RENK</span><div class="ka-menu-editor-color-row">${colors.map(c=>`<button type="button" class="ka-menu-editor-color-swatch ${c.toLowerCase()===color.toLowerCase()?'is-selected':''}" data-menu-editor-color="${c}" style="--ka-swatch:${c}" aria-label="${c} rengini seç"></button>`).join('')}<label class="ka-menu-editor-color-custom" aria-label="Özel renk seç"><span>◉</span><input type="color" data-menu-editor-color-input value="${color}"></label></div><div class="ka-menu-editor-hex"><span class="ka-menu-editor-hex__swatch" data-menu-editor-hex-swatch style="--ka-swatch:${color}"></span><input data-menu-editor-hex-input value="${color.toUpperCase()}" maxlength="7" inputmode="text" aria-label="Renk kodu"></div></section></div><footer class="ka-menu-editor-actions"><button class="ka-btn ka-btn--secondary" type="button" data-menu-editor-cancel>Vazgeç</button><button class="ka-btn ka-btn--secondary" type="button" data-menu-editor-reset>↶ Varsayılana Dön</button><button class="ka-btn" type="button" data-menu-editor-save>Kaydet</button></footer></section></div>`;bindMenuCardEditor(layer,key,g,base,color)}
function bindMenuCardEditor(layer,key,g,base,initialColor){const label=layer.querySelector('[data-menu-editor-label-input]'),counter=layer.querySelector('[data-menu-editor-counter]'),iconInput=layer.querySelector('[data-menu-editor-icon-input]'),colorInput=layer.querySelector('[data-menu-editor-color-input]'),hexInput=layer.querySelector('[data-menu-editor-hex-input]'),preview=layer.querySelector('.ka-menu-editor-preview'),previewIcon=layer.querySelector('[data-menu-editor-preview-icon]'),previewLabel=layer.querySelector('[data-menu-editor-preview-label]'),hexSwatch=layer.querySelector('[data-menu-editor-hex-swatch]');const apply=()=>{const color=validMenuColor(hexInput?.value)||validMenuColor(colorInput?.value)||initialColor;if(preview)preview.style.setProperty('--ka-menu-editor-color',color);if(hexSwatch)hexSwatch.style.setProperty('--ka-swatch',color);if(previewIcon)previewIcon.textContent=iconInput?.value.trim()||base.icon||g.icon;if(previewLabel)previewLabel.textContent=label?.value.trim()||base.label||g.label;if(counter)counter.textContent=`${label?.value.length||0}/36`};label?.addEventListener('input',apply);iconInput?.addEventListener('input',()=>{layer.querySelectorAll('[data-menu-editor-icon]').forEach(x=>x.classList.toggle('is-selected',x.dataset.menuEditorIcon===iconInput.value));apply()});layer.querySelectorAll('[data-menu-editor-icon]').forEach(b=>b.addEventListener('click',()=>{if(iconInput)iconInput.value=b.dataset.menuEditorIcon||'';layer.querySelectorAll('[data-menu-editor-icon]').forEach(x=>x.classList.toggle('is-selected',x===b));apply()}));layer.querySelectorAll('[data-menu-editor-color]').forEach(b=>b.addEventListener('click',()=>{const c=validMenuColor(b.dataset.menuEditorColor);if(!c)return;if(colorInput)colorInput.value=c;if(hexInput)hexInput.value=c.toUpperCase();layer.querySelectorAll('[data-menu-editor-color]').forEach(x=>x.classList.toggle('is-selected',x===b));apply()}));colorInput?.addEventListener('input',()=>{const c=validMenuColor(colorInput.value);if(c&&hexInput)hexInput.value=c.toUpperCase();layer.querySelectorAll('[data-menu-editor-color]').forEach(x=>x.classList.remove('is-selected'));apply()});hexInput?.addEventListener('input',()=>{let v=String(hexInput.value||'').trim().toUpperCase();if(v&&!v.startsWith('#'))v='#'+v;hexInput.value=v.slice(0,7);const c=validMenuColor(hexInput.value);if(c&&colorInput)colorInput.value=c;layer.querySelectorAll('[data-menu-editor-color]').forEach(x=>x.classList.toggle('is-selected',c&&x.dataset.menuEditorColor?.toLowerCase()===c.toLowerCase()));apply()});layer.querySelectorAll('[data-menu-editor-cancel]').forEach(b=>b.addEventListener('click',()=>{menuEditing=true;renderMenuGrid()}));layer.querySelector('[data-menu-editor-save]')?.addEventListener('click',async e=>{const btn=e.currentTarget,c=validMenuColor(hexInput?.value)||validMenuColor(colorInput?.value)||initialColor;btn.disabled=true;btn.textContent='Kaydediliyor…';try{const cfg=menuLayoutConfig(),groups={...(cfg.groups||{})},prev={...(groups[key]||{})};groups[key]={...prev,label:label?.value.trim()||base.label,icon:iconInput?.value.trim()||base.icon,color:c};menuEditing=true;await global.AppConfig?.save?.({menuLayout:{...cfg,groups}});global.toast?.('Menü kartı güncellendi.');renderMenuGrid()}catch(err){console.error('[Shell/menu-editor-save]',err);global.toast?.('Menü kartı kaydedilemedi.');btn.disabled=false;btn.textContent='Kaydet'}});layer.querySelector('[data-menu-editor-reset]')?.addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;try{const cfg=menuLayoutConfig(),groups={...(cfg.groups||{})},prev={...(groups[key]||{})};delete prev.label;delete prev.icon;delete prev.color;groups[key]=prev;menuEditing=true;await global.AppConfig?.save?.({menuLayout:{...cfg,groups}});global.toast?.(`${base.label} varsayılan görünüme döndürüldü.`);renderMenuGrid()}catch(err){console.error('[Shell/menu-editor-reset]',err);global.toast?.('Varsayılana dönülemedi.');btn.disabled=false}});apply()}
function openMenu(){closeHeaderPopover();const layer=$('#kaMenuLayer');if(!layer)return;menuEditing=false;renderMenuGrid();layer.hidden=false;requestAnimationFrame(()=>layer.classList.add('open'));document.body.classList.add('ka-layer-open');setBottomActive('menu')}
'''
text = text[:start] + block + text[end:]
p.write_text(text, encoding='utf-8')

# CSS: replace only the shell/menu visual owner portion; keep existing Settings editor styling below it.
p = Path('css/design-system.css')
text = p.read_text(encoding='utf-8')
start_marker = '/* Shell menu — compact, customizable, single canonical design owner. */'
settings_marker = '.ka-settings-menu-group>summary'
start = text.find(start_marker)
end = text.find(settings_marker, start)
if start < 0 or end < 0:
    raise SystemExit('canonical shell menu CSS section not found')
css = r'''/* Shell menu — compact card grid + single global editor entry. */
.ka-menu-grid{padding:14px max(14px,var(--ka-safe-right)) calc(22px + var(--ka-safe-bottom)) max(14px,var(--ka-safe-left));row-gap:11px;column-gap:11px}
.ka-menu-card{position:relative;min-height:122px;aspect-ratio:auto;border-radius:20px;padding:13px 13px 12px;gap:8px;align-items:flex-start;justify-content:flex-start;text-align:left;overflow:hidden;border:1px solid color-mix(in srgb,#fff 14%,transparent);box-shadow:0 6px 18px color-mix(in srgb,var(--ka-text) 10%,transparent);transition:transform var(--ka-transition-fast),box-shadow var(--ka-transition-fast),filter var(--ka-transition-fast)}
.ka-menu-card:hover{filter:saturate(1.04) brightness(1.015);box-shadow:0 9px 22px color-mix(in srgb,var(--ka-text) 13%,transparent)}.ka-menu-card:active{transform:scale(.975)}
.ka-menu-card::before{content:none!important;display:none!important}.ka-menu-card::after{content:"";position:absolute;inset:auto -28px -40px auto;width:110px;height:110px;border-radius:50%;background:color-mix(in srgb,#fff 8%,transparent);pointer-events:none}
.ka-menu-card__icon{position:relative;z-index:1;width:46px;height:46px;flex:0 0 46px;border-radius:15px;font-size:23px;border:1px solid color-mix(in srgb,#fff 18%,transparent);background:color-mix(in srgb,#fff 14%,transparent);box-shadow:inset 0 1px 0 color-mix(in srgb,#fff 16%,transparent)}
.ka-menu-card strong{position:relative;z-index:1;margin-top:auto;padding-right:28px;font-size:13.2px;line-height:1.22;text-align:left}.ka-menu-card>.ka-badge{position:absolute;z-index:2;right:10px;top:10px;min-width:25px;height:25px;padding-inline:6px;border:1px solid color-mix(in srgb,#fff 16%,transparent);background:color-mix(in srgb,#fff 17%,transparent);color:#fff;font-size:10px}
.ka-menu-card[data-menu-custom-color="true"]{background:linear-gradient(145deg,color-mix(in srgb,var(--ka-menu-custom) 94%,#fff),color-mix(in srgb,var(--ka-menu-custom) 80%,#000))!important}
.ka-menu-card[data-ka-menu-group="settings"]:last-child:nth-child(odd){grid-column:1/-1;width:100%;min-height:62px;justify-self:stretch;flex-direction:row;align-items:center;padding:9px 12px;gap:10px}.ka-menu-card[data-ka-menu-group="settings"]:last-child:nth-child(odd) .ka-menu-card__icon{width:38px;height:38px;flex-basis:38px;border-radius:12px;font-size:19px}.ka-menu-card[data-ka-menu-group="settings"]:last-child:nth-child(odd)>strong{margin:0;padding:0;flex:1}.ka-menu-card[data-ka-menu-group="settings"]:last-child:nth-child(odd)>.ka-badge{position:static;margin-left:auto}
.ka-menu-card__edit-indicator{position:absolute;left:10px;top:10px;z-index:3;width:26px;height:26px;display:grid;place-items:center;border-radius:9px;background:rgba(7,15,12,.46);color:#fff;border:1px solid rgba(255,255,255,.2);font-size:12px;box-shadow:0 3px 9px rgba(0,0,0,.12)}.ka-menu-grid--editing .ka-menu-card__icon{margin-top:28px}.ka-menu-grid--editing .ka-menu-card{outline:2px solid color-mix(in srgb,#fff 12%,transparent);outline-offset:-2px}
.ka-menu-head{min-height:68px;padding:max(10px,var(--ka-safe-top)) max(13px,var(--ka-safe-right)) 10px max(13px,var(--ka-safe-left));background:var(--ka-header-bg);backdrop-filter:none;-webkit-backdrop-filter:none}.ka-menu-head h2{font-size:20px;letter-spacing:-.02em}.ka-menu-head__actions{margin-left:auto;display:flex;align-items:center;gap:6px}.ka-menu-edit-toggle{min-height:38px;padding:0 12px;border:1px solid var(--ka-border);border-radius:13px;background:var(--ka-card-bg);color:var(--ka-text);font-size:12px;font-weight:800;cursor:pointer}.ka-menu-edit-toggle:hover,.ka-menu-edit-toggle.is-active{border-color:var(--ka-primary);background:var(--ka-primary-soft);color:var(--ka-primary)}
.ka-menu-list{padding:11px max(11px,var(--ka-safe-right)) calc(22px + var(--ka-safe-bottom)) max(11px,var(--ka-safe-left));gap:7px}.ka-menu-list>.ka-btn{min-height:58px;justify-content:flex-start;padding:7px 10px;border-radius:15px;border-color:var(--ka-border);background:var(--ka-card-bg);color:var(--ka-text);box-shadow:none;text-align:left}.ka-menu-list>.ka-btn:hover{background:var(--ka-muted-bg);color:var(--ka-text)}.ka-menu-list>.ka-btn:active{transform:scale(.995)}.ka-menu-list>.ka-btn .ka-avatar{width:40px;height:40px;flex:0 0 40px;border-radius:12px;background:var(--ka-primary-soft);color:var(--ka-primary)}.ka-menu-list>.ka-btn strong{font-size:13px}.ka-menu-list>.ka-btn>span:last-child{color:var(--ka-text-muted);display:grid;place-items:center}.ka-menu-list>.ka-btn[data-menu-custom-color="true"]{border-inline-start:3px solid var(--ka-menu-item-custom)}.ka-menu-list>.ka-btn[data-menu-custom-color="true"] .ka-avatar{background:color-mix(in srgb,var(--ka-menu-item-custom) 14%,var(--ka-card-bg));color:var(--ka-menu-item-custom)}.ka-menu-list>h3{margin:12px 2px 2px;font-size:16px}
.ka-menu-editor-screen{min-height:100%;height:100%;display:flex;align-items:flex-end;justify-content:center;padding:18px max(12px,var(--ka-safe-right)) max(0px,var(--ka-safe-bottom)) max(12px,var(--ka-safe-left));background:var(--ka-overlay);overflow:hidden}.ka-menu-editor-sheet{width:min(560px,100%);max-height:calc(100dvh - max(28px,var(--ka-safe-top)));display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--ka-border-strong);border-radius:26px 26px 0 0;background:var(--ka-card-bg);color:var(--ka-text);box-shadow:var(--ka-shadow-modal)}.ka-menu-editor-grip{width:46px;height:5px;margin:8px auto 0;border-radius:999px;background:var(--ka-border-strong)}
.ka-menu-editor-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px 11px;border-bottom:1px solid var(--ka-border)}.ka-menu-editor-head>div{min-width:0}.ka-menu-editor-head small,.ka-menu-editor-label{display:block;color:var(--ka-text-muted);font-size:10px;line-height:1.2;font-weight:900;letter-spacing:.09em}.ka-menu-editor-head h2{margin-top:3px;font-size:19px}.ka-menu-editor-body{padding:14px 16px 16px;overflow:auto;display:flex;flex-direction:column;gap:16px}.ka-menu-editor-section{display:grid;gap:8px}
.ka-menu-editor-preview{position:relative;min-height:126px;padding:16px;border-radius:20px;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;gap:9px;color:#fff;background:linear-gradient(145deg,color-mix(in srgb,var(--ka-menu-editor-color) 96%,#fff),color-mix(in srgb,var(--ka-menu-editor-color) 76%,#000));box-shadow:0 8px 22px color-mix(in srgb,var(--ka-menu-editor-color) 28%,transparent)}.ka-menu-editor-preview::after{content:"";position:absolute;right:-36px;bottom:-48px;width:150px;height:150px;border-radius:50%;background:rgba(255,255,255,.08)}.ka-menu-editor-preview__icon{width:48px;height:48px;display:grid;place-items:center;border-radius:16px;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.18);font-size:24px}.ka-menu-editor-preview strong{margin-top:auto;font-size:17px;position:relative;z-index:1}.ka-menu-editor-preview__badge{position:absolute;right:12px;top:12px;min-width:27px;height:27px;padding:0 7px;display:grid;place-items:center;border-radius:999px;background:rgba(0,0,0,.18);border:1px solid rgba(255,255,255,.18);font-size:11px;font-weight:900}
.ka-menu-editor-input-wrap{position:relative}.ka-menu-editor-input-wrap input{padding-right:58px}.ka-menu-editor-input-wrap small{position:absolute;right:12px;top:50%;transform:translateY(-50%);font-size:10px;color:var(--ka-text-muted)}.ka-menu-editor-icon-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:7px}.ka-menu-editor-icon-option{min-width:0;height:44px;border:1px solid var(--ka-border);border-radius:13px;background:var(--ka-muted-bg);color:var(--ka-text);font-size:20px;cursor:pointer}.ka-menu-editor-icon-option.is-selected{border-color:var(--ka-primary);background:var(--ka-primary-soft);box-shadow:0 0 0 2px var(--ka-focus)}.ka-menu-editor-custom-icon{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:10px;color:var(--ka-text-muted);font-size:11px;font-weight:750}.ka-menu-editor-custom-icon input{min-height:40px}
.ka-menu-editor-color-row{display:flex;align-items:center;gap:9px;overflow-x:auto;padding:3px 2px 5px;scrollbar-width:none}.ka-menu-editor-color-row::-webkit-scrollbar{display:none}.ka-menu-editor-color-swatch,.ka-menu-editor-color-custom{position:relative;width:37px;height:37px;flex:0 0 37px;border-radius:50%;border:2px solid var(--ka-card-bg);outline:1px solid var(--ka-border);background:var(--ka-swatch);cursor:pointer}.ka-menu-editor-color-swatch.is-selected{outline:3px solid var(--ka-primary);outline-offset:2px}.ka-menu-editor-color-custom{display:grid;place-items:center;background:conic-gradient(#ff3b30,#ffcc00,#34c759,#00c7be,#007aff,#af52de,#ff2d55,#ff3b30);color:#fff;font-size:15px;overflow:hidden}.ka-menu-editor-color-custom input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.ka-menu-editor-hex{display:grid;grid-template-columns:42px minmax(0,1fr);gap:9px;align-items:center}.ka-menu-editor-hex__swatch{width:42px;height:42px;border-radius:13px;background:var(--ka-swatch);border:1px solid var(--ka-border)}.ka-menu-editor-hex input{text-transform:uppercase;font-family:var(--ka-font-mono)}
.ka-menu-editor-actions{display:grid;grid-template-columns:1fr 1.15fr 1fr;gap:8px;padding:11px 16px max(12px,var(--ka-safe-bottom));border-top:1px solid var(--ka-border);background:var(--ka-card-raised-bg)}.ka-menu-editor-actions .ka-btn{min-width:0;padding-inline:9px;font-size:12px}
[data-theme="dark"] .ka-menu-card{border-color:rgba(255,255,255,.08);box-shadow:0 8px 22px rgba(0,0,0,.24)}[data-theme="dark"] .ka-menu-edit-toggle{background:#111a21;border-color:#2b3944}[data-theme="dark"] .ka-menu-editor-sheet{background:#111a21;border-color:#2b3944}[data-theme="dark"] .ka-menu-editor-actions{background:#0e171e}
@media(min-width:720px){.ka-menu-editor-screen{align-items:center;padding:24px}.ka-menu-editor-sheet{border-radius:26px;max-height:min(820px,90dvh)}}
@media(max-width:380px){.ka-menu-grid{padding-inline:max(10px,var(--ka-safe-left));gap:9px}.ka-menu-card{min-height:112px;border-radius:18px;padding:11px}.ka-menu-card__icon{width:42px;height:42px;flex-basis:42px}.ka-menu-card strong{font-size:12.2px}.ka-menu-head{padding-inline:max(10px,var(--ka-safe-left))}.ka-menu-edit-toggle{padding-inline:9px}.ka-menu-editor-body{padding:12px 13px 14px}.ka-menu-editor-head{padding-inline:13px}.ka-menu-editor-actions{padding-inline:13px}.ka-menu-editor-actions .ka-btn{font-size:11px}.ka-menu-editor-icon-grid{grid-template-columns:repeat(5,minmax(0,1fr))}}
'''
text = text[:start] + css + text[end:]
p.write_text(text, encoding='utf-8')

# PWA cache bust so installed Android/web clients fetch the new shell immediately.
p = Path('service-worker.js')
text = p.read_text(encoding='utf-8')
text = replace_once(text, "const CACHE_ADI='oy-cache-v826';", "const CACHE_ADI='oy-cache-v827';", 'service worker cache version')
p.write_text(text, encoding='utf-8')

# Strengthen the existing menu customization regression contract.
p = Path('tests/menu-customization-v2.test.js')
p.write_text(r'''const fs=require('fs');
const assert=require('assert');
const app=fs.readFileSync('js/app-loader.js','utf8');
const shell=fs.readFileSync('js/core/shell-ui.js','utf8');
const settings=fs.readFileSync('js/modules/settings.js','utf8');
const design=fs.readFileSync('css/design-system.css','utf8');
const sw=fs.readFileSync('service-worker.js','utf8');
assert(app.includes("menuLayout=r.menuLayout&&typeof r.menuLayout==='object'?r.menuLayout:{groups:{}}"),'AppConfig gerçek menuLayout alanını korumalı.');
assert(app.includes("menuLayout:{groups:{}}"),'Varsayılana dönüş classic menuLayout alanını da sıfırlamalı.');
assert(shell.includes('function menuGroupView(g,index)')&&shell.includes('function menuItemView(g,item,index,groupSettings)'),'ShellUI classic menü özelleştirmesini doğrudan render modeline uygulamalı.');
assert(shell.includes('data-menu-custom-color')&&shell.includes('customizedVisibleGroups().find'),'Ana ve alt menü özelleştirmeleri görünür renderer tarafından tüketilmeli.');
assert(shell.includes('data-ka-menu-edit')&&shell.includes('function renderMenuCardEditor(key)'),'Ana menü tek global Düzenle girişi ve kart editörü taşımalı.');
assert(shell.includes('MENU_CARD_COLOR_PRESETS')&&shell.includes('data-menu-editor-color-input')&&shell.includes('data-menu-editor-hex-input'),'Kart editörü hazır renkler, özel renk ve HEX girişi sunmalı.');
assert(shell.includes("global.AppConfig?.save?.({menuLayout:{...cfg,groups}})"),'Kart editörü mevcut AppConfig local-first sahibine kaydetmeli.');
assert(settings.includes('Ana Menü Kartları')&&settings.includes('function readMenuLayoutFromDom()')&&settings.includes('menuLayout:readMenuLayoutFromDom()'),'Gelişmiş Settings menü düzeni korunmalı.');
assert(design.includes('.ka-menu-card::before{content:none!important'),'Normal kartlarda eski dişli balonu olmamalı.');
assert(design.includes('.ka-menu-edit-toggle')&&design.includes('.ka-menu-editor-sheet')&&design.includes('.ka-menu-editor-preview'),'Yeni global düzenleme ve önizleme yüzeyi design-system sahibi olmalı.');
assert(design.includes('grid-column:1/-1;width:100%;min-height:62px'),'Tek kalan Ayarlar kartı tam genişlikte kompakt satır olmalı.');
assert(sw.includes("const CACHE_ADI='oy-cache-v827';"),'Yeni menü kabuğu için PWA cache sürümü yükseltilmeli.');
assert(!fs.existsSync('js/core/menu-customizer.js'),'İkinci runtime menu customizer sahibi geri dönmemeli.');
console.log('Menü özelleştirme + global kart editörü sözleşmesi başarılı.');
''',encoding='utf-8')

# Make the menu regression part of the canonical architecture workflow.
p = Path('.github/workflows/client-architecture.yml')
text = p.read_text(encoding='utf-8')
needle = "      - name: Verify rebuilt classic shell\n        run: node tests/classic-shell-v2-smoke.test.js\n"
insert = needle + "      - name: Verify menu customization shell\n        run: node tests/menu-customization-v2.test.js\n"
if 'Verify menu customization shell' not in text:
    text = replace_once(text, needle, insert, 'client architecture menu test')
p.write_text(text, encoding='utf-8')
